code='''from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r,c) in seen:
                continue
            q=deque([(r,c)]); seen.add((r,c)); cells=[]
            while q:
                y,x=q.popleft(); cells.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=y+dy,x+dx
                    if 0<=ny<h and 0<=nx<w and grid[ny][nx]!=0 and (ny,nx) not in seen:
                        seen.add((ny,nx)); q.append((ny,nx))
            adj={grid[y][x]:set() for y,x in cells}; boundary=set()
            for y,x in cells:
                v=grid[y][x]
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=y+dy,x+dx
                    n=grid[ny][nx] if 0<=ny<h and 0<=nx<w else 0
                    if n==0: boundary.add(v)
                    elif n!=v: adj[v].add(n)
            order=[]; cur=next(iter(boundary))
            while cur not in order:
                order.append(cur)
                nxt=[v for v in adj[cur] if v not in order]
                if not nxt: break
                cur=nxt[0]
            if len(order)<len(adj):
                order += [v for v in adj if v not in order]
            mapping=dict(zip(order, reversed(order)))
            for y,x in cells: out[y][x]=mapping[grid[y][x]]
    return out
'''
